func normalizeText(text string) string {
	text = strings.TrimSpace(text)
	if asciiTextWithoutSpaces(text) {
		return text
	}
	previousSpace := false
	canonical := true
	for _, value := range text {
		if value > ' ' && value < utf8.RuneSelf {
			previousSpace = false
			continue
		}
		if unicode.IsSpace(value) {
			if value != ' ' || previousSpace {
				canonical = false
				break
			}
			previousSpace = true
		} else {
			previousSpace = false
		}
	}
	if canonical {
		return text
	}
	return normalizeTextFields(text)
}

// Long uninterrupted text is legal content too. Inspect eight ASCII bytes at a
// time before taking the Unicode/field path. A high bit or a byte below '!'
// falls back; subtraction borrows may cause extra fallbacks, never a missed
// whitespace byte. This shortcut neither parses nor validates rich text.
func asciiTextWithoutSpaces(text string) bool {
	const highBits = uint64(0x8080808080808080)
	const minimum = uint64(0x2121212121212121)
	for len(text) >= 8 {
		word := binary.LittleEndian.Uint64([]byte(text[:8]))
		if word&highBits != 0 || (word-minimum)&highBits != 0 {
			return false
		}
		text = text[8:]
	}
	for offset := range len(text) {
		if text[offset] < '!' || text[offset] >= utf8.RuneSelf {
			return false
		}
	}
	return true
}

func normalizeTextFields(text string) string {
	// Search text needs one ASCII space between Unicode-delimited fields.
	// Keep only the first field until another arrives; a large text node must
	// not allocate one string header per word before joining the same bytes.
	var first string
	var builder strings.Builder
	appendField := func(field string) {
		if first == "" {
			first = field
			return
		}
		if builder.Len() == 0 {
			builder.Grow(len(text))
			builder.WriteString(first)
		}
		builder.WriteByte(' ')
		builder.WriteString(field)
	}
	start := -1
	for offset := 0; offset < len(text); {
		value, width := rune(text[offset]), 1
		space := value == ' ' || value >= '\t' && value <= '\r'
		if value >= utf8.RuneSelf {
			value, width = utf8.DecodeRuneInString(text[offset:])
			space = unicode.IsSpace(value)
		}
		if space {
			if start >= 0 {
				appendField(text[start:offset])
				start = -1
			}
		} else if start < 0 {
			start = offset
		}
		offset += width
	}
	if start >= 0 {
		appendField(text[start:])
	}
	if builder.Len() != 0 {
		return builder.String()
	}
	return first
}

// ContentSchemaVersion reads only the bounded envelope used for compatibility decisions.
func ContentSchemaVersion(raw []byte) int {
	if !json.Valid(raw) {
		return 1
	}
	return contentSchemaVersionSpans(raw)
}

func contentSchemaVersionSpans(raw []byte) int {
	var envelope struct {
		SchemaVersion int `json:"schema_version"`
	}
	if visitJSONObject(raw, func(key string, value []byte) error {
		if strings.EqualFold(key, "schema_version") {
			return json.Unmarshal(value, &envelope.SchemaVersion)
		}
		return nil
	}) != nil {
		return 1
	}
	if envelope.SchemaVersion == 2 {
		return 2
	}
	return 1
}

// RefuseSchemaDowngrade prevents an older client from replacing a schema-2 body.
func RefuseSchemaDowngrade(previous, next []byte) error {
	// Schema 1 is the floor, including the legacy/invalid-envelope fallback.
	// Only an existing schema-2 body needs the next envelope decoded.
	if ContentSchemaVersion(previous) == 2 && ContentSchemaVersion(next) < 2 {
		return ErrInvalidVersion
	}
	return nil
}

// PromoteTables changes only the envelope; structural content and CRDT identity are unchanged.
func PromoteTables(raw []byte) ([]byte, error) {
	if len(raw) == 0 {
		raw = Empty()
	}
	validated, err := Validate(raw, MaxDocumentBytes)
	if err != nil {
		return nil, err
	}
	var value Document
	if err = json.Unmarshal(validated.JSON, &value); err != nil {
		return nil, err
	}
	value.SchemaVersion = TableSchemaVersion
	return json.Marshal(value)
}
